entry.string:
@echo off
setlocal EnableDelayedExpansion
set READY=0
for /L %%i in (1,1,10) do (
    curl.exe --fail --silent --show-error "%PARABANK_URL%/index.htm" > nul 2>&1
    if !errorlevel! equ 0 (
        set READY=1
        timeout /t 5 /nobreak > nul
        goto :ready
    )
    timeout /t 3 /nobreak > nul
)
:ready
if "!READY!"=="0" exit /b 1
